<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {evaluationApi,projectsApi,type EvaluationSample,type EvaluationSampleInput,type EvaluationRun,type EvaluationRunInput,type EvaluationComparison} from '../api'
import {errorMessage,formatDate} from '../utils'
import EvaluationMetrics from '../components/EvaluationMetrics.vue'
const pid=Number(useRoute().params.projectId),router=useRouter(),name=ref(''),samples=ref<EvaluationSample[]>([]),runs=ref<EvaluationRun[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref(''),tab=ref('samples')
const sampleDialog=ref(false),runDialog=ref(false),editingId=ref(''),saving=ref(false),formError=ref(''),points=ref(''),original=ref('')
function defaults():EvaluationSampleInput{return {name:'',requirement_title:'',requirement_content:'',feature:{module:'评测',feature:'',description:'',acceptance_criteria:'',constraints:'',priority:'P1'},gold_points:[],expected_revision:0}}
const form=ref(defaults()),runForm=ref<Omit<EvaluationRunInput,'run_id'>>({name:'',sample_ids:[],strategy:'full',skill_ids:[],mock_mode:false,use_rag:false,rag_top_k:3,rag_rerank:false,rag_allow_empty:false})
const runOriginal=ref(''),left=ref(''),right=ref(''),comparison=ref<EvaluationComparison>(),comparing=ref(false)
const finished=computed(()=>runs.value.filter(run=>!['queued','running','stopping'].includes(run.status)))
const dirty=computed(()=>(sampleDialog.value&&JSON.stringify([form.value,points.value])!==original.value)||(runDialog.value&&JSON.stringify(runForm.value)!==runOriginal.value))
let pending:{signature:string;id:string}|undefined
async function load(){loading.value=true;error.value='';try{const[p,s,r]=await Promise.all([projectsApi.get(pid),evaluationApi.samples(pid),evaluationApi.runs(pid,(page.value-1)*20)]);name.value=p.name;samples.value=s;runs.value=r.items;total.value=r.total}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function openSample(sample?:EvaluationSample){editingId.value=sample?.id||'';form.value=sample?{name:sample.name,requirement_title:sample.content.requirement.title,requirement_content:sample.content.requirement.content,feature:{module:sample.content.feature.module,feature:sample.content.feature.feature,description:sample.content.feature.description,acceptance_criteria:sample.content.feature.acceptance_criteria,constraints:sample.content.feature.constraints,priority:sample.content.feature.priority},gold_points:sample.content.gold_points,expected_revision:sample.revision}:defaults();points.value=sample?.content.gold_points.join('\n')||'';original.value=JSON.stringify([form.value,points.value]);formError.value='';sampleDialog.value=true}
async function saveSample(){saving.value=true;formError.value='';try{const data={...form.value,gold_points:points.value.split('\n').map(v=>v.trim()).filter(Boolean)};if(editingId.value)await evaluationApi.edit(pid,editingId.value,data);else await evaluationApi.add(pid,data);sampleDialog.value=false;await load()}catch(e){formError.value=errorMessage(e)+' 保存结果不明时先刷新样本列表核对。'}finally{saving.value=false}}
async function remove(sample:EvaluationSample){try{await ElMessageBox.confirm(`删除样本「${sample.name}」？历史运行快照保留。`,'删除评测样本',{type:'warning'});await evaluationApi.remove(pid,sample);await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorMessage(e)}}
function openRun(){runForm.value={name:'',sample_ids:[],strategy:'full',skill_ids:[],mock_mode:false,use_rag:false,rag_top_k:3,rag_rerank:false,rag_allow_empty:false};runOriginal.value=JSON.stringify(runForm.value);pending=undefined;formError.value='';runDialog.value=true}
async function submit(){saving.value=true;formError.value='';try{if(!runForm.value.name.trim()||!runForm.value.sample_ids.length)throw Error('请填写运行名并选择样本。');const data={...runForm.value,name:runForm.value.name.trim(),rag_rerank:runForm.value.use_rag&&runForm.value.rag_rerank,rag_allow_empty:runForm.value.use_rag&&runForm.value.rag_allow_empty};const signature=JSON.stringify(data);if(!pending||pending.signature!==signature)pending={signature,id:crypto.randomUUID()};const run=await evaluationApi.submit(pid,{...data,run_id:pending.id});runDialog.value=false;saving.value=false;await router.push(`/projects/${pid}/evaluations/runs/${run.id}`)}catch(e){formError.value=errorMessage(e)+' 提交结果不明时先刷新运行列表核对；相同内容重试沿用请求标识。'}finally{saving.value=false}}
async function compare(){comparing.value=true;error.value='';comparison.value=undefined;try{comparison.value=await evaluationApi.compare(pid,left.value,right.value)}catch(e){error.value=errorMessage(e)}finally{comparing.value=false}}
async function discard(){if(saving.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('放弃未保存的评测配置？','未保存的修改',{type:'warning',confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});return true}catch{return false}}
async function closeSample(done:()=>void){if(await discard()){sampleDialog.value=false;done()}}
async function closeRun(done:()=>void){if(await discard()){runDialog.value=false;done()}}
function unload(e:BeforeUnloadEvent){if(dirty.value||saving.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(discard);onBeforeRouteUpdate(discard);onMounted(()=>{window.addEventListener('beforeunload',unload);void load()});onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
</script>
<template><main><router-link to="/" class="back-link">← 项目列表</router-link><div class="page-heading"><div><div class="eyebrow">OFFLINE EVALUATION</div><h1>{{name||'项目'}} · 离线评测</h1><p>独立固定样本集，评测产物与正式需求、用例和人工执行记录隔离。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-tabs v-model="tab"><el-tab-pane label="评测样本" name="samples"><div class="evaluation-toolbar"><p>每个样本包含一项人工定义功能点和可选的标准测试点。</p><el-button type="primary" :disabled="loading" @click="openSample()">新建评测样本</el-button></div><article v-for="sample in samples" :key="sample.id" class="case-card"><h3>{{sample.name}}</h3><p>{{sample.content.requirement.title}} / {{sample.content.feature.feature}}</p><p class="field-help">版本 {{sample.revision}} · {{sample.content.gold_points.length}} 个标准点 · 更新 {{formatDate(sample.updated_at)}}</p><details><summary>样本内容</summary><pre>{{sample.content.requirement.content}}</pre><p>标准点：{{sample.content.gold_points.join('；')||'未提供，不计算召回'}}</p></details><el-button :disabled="loading" @click="openSample(sample)">编辑样本</el-button><el-button type="danger" plain :disabled="loading" @click="remove(sample)">删除样本</el-button></article><el-empty v-if="!samples.length&&!loading" description="先录入需求与人工标准测试点"/></el-tab-pane>
<el-tab-pane label="批量运行" name="runs"><div class="evaluation-toolbar"><p>每次最多 20 个样本，同一项目一次活动运行。</p><el-button type="primary" :disabled="loading||!samples.length" @click="openRun">新建评测运行</el-button></div><article v-for="run in runs" :key="run.id" class="case-card"><h3><router-link :to="`/projects/${pid}/evaluations/runs/${run.id}`">{{run.name}}</router-link></h3><p>{{run.status}} · {{run.config_snapshot.mock_mode?'Mock 演示':'真实评测'}} · 完成 {{run.finished_count}}/{{run.sample_count}} · {{formatDate(run.created_at)}}</p><EvaluationMetrics :value="run.metrics"/><router-link :to="`/projects/${pid}/evaluations/runs/${run.id}`" class="row-link">查看样本明细与快照 →</router-link></article><el-empty v-if="!runs.length&&!loading" description="尚无评测运行"/></el-tab-pane>
<el-tab-pane label="两次运行对比" name="compare"><p>先选择两次已结束的运行，仅相同 ID 且内容哈希相同的样本参与共同指标。</p><div class="evaluation-toolbar"><el-select v-model="left" aria-label="左侧评测运行"><el-option v-for="run in finished" :key="run.id" :value="run.id" :label="`${run.name} · ${run.id.slice(0,8)}`"/></el-select><el-select v-model="right" aria-label="右侧评测运行"><el-option v-for="run in finished" :key="run.id" :value="run.id" :label="`${run.name} · ${run.id.slice(0,8)}`"/></el-select><el-button type="primary" :loading="comparing" :disabled="!left||!right||left===right" @click="compare">对比运行</el-button></div><template v-if="comparison"><el-alert :title="comparison.note" type="info" :closable="false"/><p>共同可比 {{comparison.common_count}} · 内容变更排除 {{comparison.changed_sample_ids.length}} · 仅左 {{comparison.left_only_ids.length}} · 仅右 {{comparison.right_only_ids.length}}</p><el-alert v-if="!comparison.metric_definitions_equal" title="指标定义或门槛版本不同，请结合规则差异解释，不直接判断优劣。" type="warning" :closable="false"/><h3>左：{{comparison.left.name}} · 共同样本指标</h3><EvaluationMetrics :value="comparison.common_metrics.left"/><h3>右：{{comparison.right.name}} · 共同样本指标</h3><EvaluationMetrics :value="comparison.common_metrics.right"/><details><summary>配置与版本差异（{{comparison.config_differences.length}}）</summary><pre>{{JSON.stringify(comparison.config_differences,null,2)}}</pre></details><details><summary>样本差异与共同样本逐项结果</summary><pre>{{JSON.stringify({changed:comparison.changed_sample_ids,left_only:comparison.left_only_ids,right_only:comparison.right_only_ids,common:comparison.rows},null,2)}}</pre></details></template></el-tab-pane></el-tabs><el-pagination v-if="tab!=='samples'&&total>20" v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/>
<el-dialog v-model="sampleDialog" :title="editingId?'编辑评测样本':'新建评测样本'" width="min(760px,95vw)" :close-on-click-modal="false" :before-close="closeSample"><el-form label-position="top" :disabled="saving"><el-form-item label="样本名称"><el-input v-model="form.name" maxlength="100" aria-label="评测样本名称"/></el-form-item><el-form-item label="需求标题"><el-input v-model="form.requirement_title" maxlength="200" aria-label="评测需求标题"/></el-form-item><el-form-item label="需求原文"><el-input v-model="form.requirement_content" type="textarea" :rows="5" maxlength="50000" aria-label="评测需求原文"/></el-form-item><el-form-item label="模块"><el-input v-model="form.feature.module" maxlength="100"/></el-form-item><el-form-item label="功能点名称"><el-input v-model="form.feature.feature" maxlength="200" aria-label="评测功能点"/></el-form-item><el-form-item label="功能描述"><el-input v-model="form.feature.description" type="textarea" :rows="2" maxlength="4000" aria-label="评测功能描述"/></el-form-item><el-form-item label="验收标准（生成可见）"><el-input v-model="form.feature.acceptance_criteria" type="textarea" :rows="2" maxlength="4000"/></el-form-item><el-form-item label="约束"><el-input v-model="form.feature.constraints" type="textarea" maxlength="2000"/></el-form-item><el-form-item label="人工标准测试点（生成不可见，每行一个，最多20个，每项2–500字）"><el-input v-model="points" type="textarea" :rows="5" aria-label="人工标准测试点"/><p class="field-help">本版按整段词面包含匹配，过长或不同措辞可能漏匹配；无标准点不计算召回率。</p></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button :disabled="saving" @click="closeSample(()=>sampleDialog=false)">取消</el-button><el-button type="primary" :loading="saving" @click="saveSample">保存评测样本</el-button></template></el-dialog>
<el-dialog v-model="runDialog" title="新建评测运行" width="min(760px,95vw)" :close-on-click-modal="false" :before-close="closeRun"><el-alert title="真实评测每个成功样本通常有一次生成和一次 Judge 调用；RAG 可能增加 Embedding/Rerank 调用并计费。不会自动重试。离线指固定数据集，真实模型仍需联网。" type="info" :closable="false"/><el-form label-position="top" :disabled="saving"><el-form-item label="运行名称"><el-input v-model="runForm.name" maxlength="100" aria-label="评测运行名称"/></el-form-item><el-switch v-model="runForm.mock_mode" active-text="本次 Mock 演示（不改全局配置，不调用外部服务）" @change="runForm.rag_rerank=false"/><el-form-item label="策略"><el-select v-model="runForm.strategy" aria-label="评测生成策略"><el-option label="完整：功能/边界/异常" value="full"/><el-option label="冒烟：关键功能" value="quick"/></el-select></el-form-item><el-form-item label="专项"><el-checkbox-group v-model="runForm.skill_ids"><el-checkbox value="api">接口测试</el-checkbox><el-checkbox value="security">安全与权限</el-checkbox></el-checkbox-group></el-form-item><el-checkbox v-model="runForm.use_rag">使用项目知识 RAG</el-checkbox><template v-if="runForm.use_rag"><el-form-item label="知识条数"><el-input-number v-model="runForm.rag_top_k" :min="1" :max="5"/></el-form-item><el-checkbox v-model="runForm.rag_rerank" :disabled="runForm.mock_mode">启用 Rerank</el-checkbox><el-checkbox v-model="runForm.rag_allow_empty">无知识时仍继续（保存降级记录）</el-checkbox><p v-if="runForm.mock_mode" class="field-help">Mock 知识只使用本地 BM25，不运行向量或精排。</p></template><h3>选择样本 {{runForm.sample_ids.length}} / 20</h3><el-checkbox-group v-model="runForm.sample_ids" :max="20" class="evaluation-picker"><el-checkbox v-for="sample in samples" :key="sample.id" :value="sample.id">{{sample.name}} · v{{sample.revision}}</el-checkbox></el-checkbox-group></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button :disabled="saving" @click="closeRun(()=>runDialog=false)">取消</el-button><el-button type="primary" :loading="saving" :disabled="!runForm.sample_ids.length" @click="submit">提交批量评测</el-button></template></el-dialog></main></template>
<style scoped>.evaluation-toolbar{display:flex;gap:16px;align-items:center;margin:18px 0}.evaluation-toolbar .el-select{width:260px}.evaluation-picker{display:flex;flex-direction:column;max-height:300px;overflow:auto}.case-card{margin-bottom:18px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:450px;overflow:auto;background:#f5f7fa;padding:12px}details{margin:18px 0}.el-form{margin-top:18px}</style>
